from fractions import Fraction
import numpy as np

def show(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def cross(u, v):
    return [u[1] * v[2] - u[2] * v[1],
            u[2] * v[0] - u[0] * v[2],
            u[0] * v[1] - u[1] * v[0]]

def floats(v):
    return [float(x) for x in v]

def cross_steps(label, u, v):
    print(f"{label}: {show(u)} × {show(v)}")
    w = cross(u, v)
    names = ["first", "second", "third"]
    pairs = [(1, 2), (2, 0), (0, 1)]
    for k in range(3):
        a, b = pairs[k]
        p, q = u[a] * v[b], u[b] * v[a]
        print(f"  {names[k]}: {paren(u[a])}({v[b]}) - {paren(u[b])}({v[a]}) = {p} - {paren(q)} = {w[k]}")
    print(f"  u × v = {show(w)}")
    print(f"  checks: u·(u × v) = {dot(u, w)}, v·(u × v) = {dot(v, w)}")
    print(f"  numpy agrees: {np.allclose(np.cross(floats(u), floats(v)), floats(w))}")

cross_steps("Case 1 · the axes", [1, 0, 0], [0, 1, 0])
cross_steps("Case 2 · the order reversed", [0, 1, 0], [1, 0, 0])
cross_steps("Case 3 · the plain case", [1, 2, 3], [4, 5, 6])
cross_steps("Case 4 · negatives and a zero", [2, -1, 0], [1, 3, -2])
cross_steps("Case 5 · parallel vectors", [1, 2, 3], [2, 4, 6])
cross_steps("Case 6 · torque", [Fraction(1, 4), 0, 0], [0, 40, 0])

