from fractions import Fraction

def show(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def term(p, d):
    if d == 0:
        return str(p)
    c = "" if abs(d) == 1 else str(abs(d))
    sign = "+" if d > 0 else "-"
    return f"{p} {sign} {c}t"

def line_steps(label, P, Q, X):
    print(f"{label}: the line through {show(P)} and {show(Q)}")
    d = [Q[i] - P[i] for i in range(3)]
    print(f"  d = Q - P = {show(d)}")
    names = ["x", "y", "z"]
    print("  " + ", ".join(f"{names[i]} = {term(P[i], d[i])}" for i in range(3)))
    ts = []
    fixed_ok = True
    for i in range(3):
        if d[i] == 0:
            print(f"  {names[i]}: stays {P[i]}, and X has {X[i]}")
            fixed_ok = fixed_ok and X[i] == P[i]
        else:
            t = (X[i] - P[i]) / d[i]
            print(f"  {names[i]}: {term(P[i], d[i])} = {X[i]} gives t = {t}")
            ts.append(t)
    if fixed_ok and all(t == ts[0] for t in ts):
        print(f"  {show(X)} is on the line, at t = {ts[0]}")
    else:
        print(f"  {show(X)} is off the line")

n = int(input())
for k in range(n):
    P = [Fraction(t) for t in input().split()]
    Q = [Fraction(t) for t in input().split()]
    X = [Fraction(t) for t in input().split()]
    line_steps(f"Problem {k + 1}", P, Q, X)

