import math

def show(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def cross(u, v):
    return [u[1] * v[2] - u[2] * v[1],
            u[2] * v[0] - u[0] * v[2],
            u[0] * v[1] - u[1] * v[0]]

def equation(n, d):
    text = ""
    for i in range(3):
        a = n[i]
        if a == 0:
            continue
        c = "" if abs(a) == 1 else str(abs(a))
        if text == "":
            text = ("-" if a < 0 else "") + c + "xyz"[i]
        else:
            text += (" - " if a < 0 else " + ") + c + "xyz"[i]
    return f"{text} = {d}"

def plane_steps(label, P, Q, R, X):
    print(f"{label}: P{show(P)}, Q{show(Q)}, R{show(R)}")
    PQ = [Q[i] - P[i] for i in range(3)]
    PR = [R[i] - P[i] for i in range(3)]
    n = cross(PQ, PR)
    print(f"  PQ = {show(PQ)}, PR = {show(PR)}, n = PQ × PR = {show(n)}")
    if n == [0, 0, 0]:
        print("  n is zero: the points are on one line, so no single plane")
        return
    g = math.gcd(n[0], n[1], n[2])
    if g > 1:
        n = [x // g for x in n]
        print(f"  divide by the common factor {g}: n = {show(n)}")
    d = dot(n, P)
    print(f"  d = n·P = {d}, so the plane is {equation(n, d)}")
    print(f"  checks: n·Q = {dot(n, Q)}, n·R = {dot(n, R)}")
    if dot(n, X) == d:
        print(f"  X{show(X)}: n·X = {dot(n, X)}, on the plane")
    else:
        print(f"  X{show(X)}: n·X = {dot(n, X)}, not {d}, so off the plane")

plane_steps("Case 1 · corners on the axes", [1, 0, 0], [0, 2, 0], [0, 0, 3], [1, 1, 1])
plane_steps("Case 2 · through the origin", [0, 0, 0], [1, 0, -1], [0, 1, -1], [2, 3, -5])
plane_steps("Case 3 · the roof", [0, 0, 3], [4, 0, 3], [0, 5, 6], [2, 10, 9])
plane_steps("Case 4 · a normal with negatives", [1, 2, 3], [2, 0, 3], [1, 3, 7], [0, 0, 0])
plane_steps("Case 5 · points on one line", [1, 1, 1], [2, 3, 4], [3, 5, 7], [0, 0, 0])

